import{_ as a,o as r,c as o,ao as t}from"./chunks/framework.C26bghZo.js";const u=JSON.parse('{"title":"Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md","lastUpdated":null}'),n={name:"reference/index.md"};function s(c,e,i,l,d,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="Reference" tabindex="-1">Reference <a class="header-anchor" href="#Reference" aria-label="Permalink to &quot;Reference {#Reference}&quot;">​</a></h1><p>A complete manual covering every public function in Polars.jl, organized by type — mirroring the structure of the <a href="https://docs.pola.rs/api/python/stable/reference/index.html" target="_blank" rel="noreferrer">py-polars API reference</a>. Use this once you know roughly what you&#39;re looking for; for a guided introduction, start with the tutorials instead.</p><h2 id="Core-types" tabindex="-1">Core types <a class="header-anchor" href="#Core-types" aria-label="Permalink to &quot;Core types {#Core-types}&quot;">​</a></h2><ul><li><p><a href="/Polars.jl/dev/reference/dataframe#DataFrame">DataFrame</a> — the eager, columnar table type, and every verb that operates on it (<code>select</code>, <code>filter</code>, <code>sort</code>, <code>group_by</code>/<code>agg</code>, joins, reshaping, ...) — shared with <code>LazyFrame</code>.</p></li><li><p><a href="/Polars.jl/dev/reference/lazyframe#LazyFrame">LazyFrame</a> — the lazy, query-plan type: <code>lazy</code>, <code>collect</code>, <code>collect_schema</code>, and <code>LazyGroupBy</code>.</p></li><li><p><a href="/Polars.jl/dev/reference/series#Series">Series</a> — a single named column.</p></li><li><p><a href="/Polars.jl/dev/reference/expressions#Expressions">Expressions</a> — <code>Expr</code>, the building block of every query: aggregation, boolean, math, manipulation, naming, and casting functions.</p></li></ul><h2 id="Functions-and-selection" tabindex="-1">Functions &amp; selection <a class="header-anchor" href="#Functions-and-selection" aria-label="Permalink to &quot;Functions &amp; selection {#Functions-and-selection}&quot;">​</a></h2><ul><li><p><a href="/Polars.jl/dev/reference/functions#Functions">Functions</a> — top-level expression constructors: <code>col</code>, <code>lit</code>, <code>when</code>, and horizontal (row-wise) reductions.</p></li><li><p><a href="/Polars.jl/dev/reference/selectors#Selectors">Selectors</a> — select columns by dtype, name, position, or pattern instead of one <code>col(...)</code> at a time.</p></li></ul><h2 id="Expression-namespaces" tabindex="-1">Expression namespaces <a class="header-anchor" href="#Expression-namespaces" aria-label="Permalink to &quot;Expression namespaces {#Expression-namespaces}&quot;">​</a></h2><ul><li><p><a href="/Polars.jl/dev/reference/expr-list#expr-list">List</a> — the <code>Lists</code> namespace, for list-typed columns.</p></li><li><p><a href="/Polars.jl/dev/reference/expr-string#expr-string">String</a> — the <code>Strings</code> namespace, for <code>String</code>-typed columns.</p></li><li><p><a href="/Polars.jl/dev/reference/expr-datetime#expr-datetime">Datetime</a> — the <code>Dt</code> namespace, for <code>Date</code>/<code>Datetime</code>/<code>Duration</code> columns.</p></li><li><p><a href="/Polars.jl/dev/reference/expr-struct#expr-struct">Struct</a> — the <code>Structs</code> namespace, for struct-typed columns.</p></li><li><p><a href="/Polars.jl/dev/reference/expr-meta#expr-meta">Meta</a> — the <code>Polars.Meta</code> namespace, for inspecting an expression tree itself.</p></li></ul><h2 id="I/O,-types-and-misc" tabindex="-1">I/O, types &amp; misc <a class="header-anchor" href="#I/O,-types-and-misc" aria-label="Permalink to &quot;I/O, types &amp; misc {#I/O,-types-and-misc}&quot;">​</a></h2><ul><li><p><a href="/Polars.jl/dev/reference/io#Input/output">Input/output</a> — reading, writing, and streaming parquet/CSV/IPC files.</p></li><li><p><a href="/Polars.jl/dev/reference/datatypes#Data-types">Data types</a> — the Julia↔polars dtype mapping and nullability convention.</p></li><li><p><a href="/Polars.jl/dev/reference/metadata#Metadata">Metadata</a> — <code>Polars.version()</code>.</p></li><li><p><a href="/Polars.jl/dev/reference/exceptions#Exceptions">Exceptions</a> — <code>PolarsError</code>, the single exception type every fallible operation raises.</p></li></ul>',10)])])}const h=a(n,[["render",s]]);export{u as __pageData,h as default};
